	test: {
		setupFiles: ["./test/setup/apply-migrations.ts"],
		poolOptions: {
			workers: {
				singleWorker: true,
				wrangler: { configPath: testConfigPath },
				miniflare: {
					bindings: {
						TEST_MIGRATIONS: migrations,
						// Override BETTER_AUTH_URL from .env (https) so better-auth uses
